let filterDeposit (contract: Contract) (fromBlock: BlockParameter) (toBlock: BlockParameter) =
    let filter = contract.GetEventBySignature("0x5548c837ab068cf56a2c2479df0882a4922fd203edb7517321831d95078c5f62").CreateFilterInput(fromBlock, toBlock)
    filter

let decodeDepositEvent (contract: Contract) (log: FilterLog) : DepositEvent =
    let decoded = contract.GetEventBySignature("0x5548c837ab068cf56a2c2479df0882a4922fd203edb7517321831d95078c5f62").DecodeAllEventsForEvent<DepositEvent>([| log |])
    if decoded.Count <> 1 then invalidArg "log" "Log does not match event"
    decoded.[0].Event

let queryDeposit (contract: Contract) (filter: NewFilterInput) =
    if isNull filter || isNull filter.Address || not (filter.Address |> Array.exists (fun address -> String.Equals(address, contract.Address, StringComparison.OrdinalIgnoreCase))) then invalidArg "filter" "Filter must include this contract address"
    task {
        let! logs = contract.Eth.Filters.GetLogs.SendRequestAsync(filter)
        let result = ResizeArray<EventLog<DepositEvent>>()
        let event = contract.GetEventBySignature("0x5548c837ab068cf56a2c2479df0882a4922fd203edb7517321831d95078c5f62")
        for log in logs do
            if String.Equals(log.Address, contract.Address, StringComparison.OrdinalIgnoreCase) && event.IsLogForEvent(log) then
                result.Add(EventLog<DepositEvent>(decodeDepositEvent contract log, log))
        return result
    }

